using System.ComponentModel.DataAnnotations;

namespace OpsFlow.Api.Contracts;

/// <summary>ClientMessageId is generated by the client once per message and reused on retries, so a retry returns the original instead of a duplicate.</summary>
public sealed record SendMessageRequest(
    [Required, StringLength(4000, MinimumLength = 1)] string Content,
    [Required] Guid? ClientMessageId
);
